calc.mjs.text:
// Pure bid arithmetic for well-pump and pressure-tank replacement.
// No network, no state: every foot of drop pipe, horsepower, wage, and
// wear charge is an input, so the result stays a transparent calculation
// the shop can check against their own invoices rather than a claim about
// what any well "should" cost.
//
// The method is the one the trade actually loses money on: a flat
// "$1,495 well-pump special" treats a 60-foot 1/2 HP swap with a good
// pitless adapter as the same job as a 280-foot 1.5 HP pull with a
// seized pitless, a stuck pump, a new tank, extra well cable, and a
// constant-pressure drive. Homeowners (and a lot of estimator sheets)
// count the same kind of number. Extra drop-pipe footage, extra cable,
// the tank, a stuck pull, and a seized pitless do not scale with the
// trip charge. Matching a cheaper special written for the brochure
// shallow well is how a sold deep-well job becomes a half-day loss
// after the first seized adapter.
//
// Distinct from water-heater replacement (vent, gas upsize, attic),
// septic pumping (a tank lid, hose, and extra gallons), hydro-jet /
// sewer-camera work (a drain line and a toilet pull), and electrical-
// panel upgrades (a feeder and a utility). This prices a well: the
// pump, the depth past the included footage, how the pitless comes
// apart, and the tank that keeps the well from short-cycling.

export const TYPE_PRESETS = Object.freeze([
  { id: 'submersible', label: 'Submersible (in the well)' },
  { id: 'jet', label: 'Jet / shallow (above ground)' },
]);

export const WORK_PRESETS = Object.freeze([
  { id: 'pump', label: 'Pump only (keep the tank)' },
  { id: 'pump-tank', label: 'Pump + pressure tank' },
  { id: 'full', label: 'Pump, tank, pitless, and switch' },
]);

export const HP_PRESETS = Object.freeze([
  { id: '0.5', label: '1/2 HP' },
  { id: '0.75', label: '3/4 HP' },
  { id: '1', label: '1 HP' },
  { id: '1.5', label: '1.5 HP' },
]);

export const PITLESS_PRESETS = Object.freeze([
  { id: 'good', label: 'Existing pitless comes apart' },
  { id: 'seized', label: 'Seized pitless — replace it' },
  { id: 'none', label: 'No pitless (jet / buried pit)' },
]);

export const JOB_PRESETS = Object.freeze([
  {
    label: '60 ft 1/2 HP submersible, keep the tank (the $1,495 brochure special)',
    type: 'submersible',
    work: 'pump',
    hp: '0.5',
    pitless: 'good',
    wellDepthFeet: 60,
    includedFootage: 100,
    cableFeet: 70,
    includedCableFeet: 100,
    stuckPump: false,
    addVfd: false,
  },
  {
    label: '120 ft 3/4 HP submersible, new tank, good pitless',
    type: 'submersible',
    work: 'pump-tank',
    hp: '0.75',
    pitless: 'good',
    wellDepthFeet: 120,
    includedFootage: 100,
    cableFeet: 130,
    includedCableFeet: 100,
    stuckPump: false,
    addVfd: false,
  },
  {
    label: '280 ft 1.5 HP, seized pitless, stuck pump, new tank, extra cable, VFD',
    type: 'submersible',
    work: 'full',
    hp: '1.5',
    pitless: 'seized',
    wellDepthFeet: 280,
    includedFootage: 100,
    cableFeet: 300,
    includedCableFeet: 100,
    stuckPump: true,
    addVfd: true,
  },
  {
    label: '40 ft jet pump + tank, no pitless (shallow well)',
    type: 'jet',
    work: 'pump-tank',
    hp: '0.75',
    pitless: 'none',
    wellDepthFeet: 40,
    includedFootage: 100,
    cableFeet: 20,
    includedCableFeet: 100,
    stuckPump: false,
    addVfd: false,
  },
]);

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

function flag(value) {
  if (value === true || value === 'true' || value === '1' || value === 1) return true;
  if (value === false || value === 'false' || value === '0' || value === 0 || value === '' || value == null) {
    return false;
  }
  return Boolean(value);
}

/**
 * Starting pump cost from horsepower and type. These are ballpark
 * shop figures, not a catalog. Picking HP or type never overwrites a
 * cost the shop has already typed.
 */
export function suggestedHpKit(hp, type = 'submersible') {
  const id = String(hp);
  const kind = String(type);
  const table = kind === 'jet'
    ? { '0.5': 220, '0.75': 300, '1': 420, '1.5': 620 }
    : { '0.5': 280, '0.75': 380, '1': 520, '1.5': 780 };
  if (!(id in table)) throw new Error('Unknown horsepower');
  return { pumpCost: table[id] };
}

/**
 * Starting pull hours and hoist wear from the pump type. A jet pump
 * sits above ground. A submersible has to come out of the well.
 */
export function suggestedTypeKit(type) {
  const id = String(type);
  if (id === 'submersible') {
    return { hoursPumpBase: 2.5, hoistFee: 75 };
  }
  if (id === 'jet') {
    return { hoursPumpBase: 1.5, hoistFee: 0 };
  }
  throw new Error('Unknown pump type');
}

/**
 * Starting tank and switch hours and materials from the work package.
 * Pump-only keeps the existing tank. Full work also bills the switch.
 */
export function suggestedWorkKit(work) {
  const id = String(work);
  if (id === 'pump') {
    return { hoursTank: 0, tankCost: 0, hoursSwitch: 0, switchCost: 0 };
  }
  if (id === 'pump-tank') {
    return { hoursTank: 1, tankCost: 280, hoursSwitch: 0, switchCost: 0 };
  }
  if (id === 'full') {
    return { hoursTank: 1, tankCost: 280, hoursSwitch: 0.5, switchCost: 85 };
  }
  throw new Error('Unknown work package');
}

/**
 * Starting pitless hours and fittings from how the adapter comes
 * apart. A good existing pitless is free access. A seized one is not.
 * Jet pumps often have no pitless at all.
 */
export function suggestedPitlessKit(pitless) {
  const id = String(pitless);
  if (id === 'good' || id === 'none') {
    return { hoursPitless: 0, pitlessCost: 0 };
  }
  if (id === 'seized') {
    return { hoursPitless: 2, pitlessCost: 185 };
  }
  throw new Error('Unknown pitless condition');
}

/**
 * Price a well-pump replacement from depth past the included footage,
 * horsepower, tank, pitless, stuck pull, extra cable, a constant-
 * pressure drive, and the contractor's own costs.
 *
 * @param {object} input
 */
export function calculateBid(input) {
  const wellDepthFeet = number(input.wellDepthFeet ?? 0, 'Well depth', { allowZero: false });
  const includedFootage = number(input.includedFootage ?? 0, 'Included footage');
  const cableFeet = number(input.cableFeet ?? 0, 'Well-cable footage');
  const includedCableFeet = number(input.includedCableFeet ?? 0, 'Included cable footage');
  // A brochure special that "includes the first 100 ft" still prices a
  // shallower well — extra footage is zero, not an invalid takeoff.

  const type = String(input.type ?? 'submersible');
  if (!TYPE_PRESETS.some((item) => item.id === type)) {
    throw new Error('Unknown pump type');
  }
  const work = String(input.work ?? 'pump-tank');
  if (!WORK_PRESETS.some((item) => item.id === work)) {
    throw new Error('Unknown work package');
  }
  const hp = String(input.hp ?? '0.75');
  if (!HP_PRESETS.some((item) => item.id === hp)) {
    throw new Error('Unknown horsepower');
  }
  const pitless = String(input.pitless ?? 'good');
  if (!PITLESS_PRESETS.some((item) => item.id === pitless)) {
    throw new Error('Unknown pitless condition');
  }

  const stuckPump = flag(input.stuckPump);
  const addVfd = flag(input.addVfd);
  const replaceTank = work === 'pump-tank' || work === 'full';
  const replaceSwitch = work === 'full';
  const replacePitless = pitless === 'seized';
  const extraFeet = Math.max(0, wellDepthFeet - includedFootage);
  const extraCableFeet = Math.max(0, cableFeet - includedCableFeet);

  const hoursTrip = number(input.hoursTrip ?? 0, 'Hours for the trip / setup');
  const hoursPumpBase = number(input.hoursPumpBase ?? 0, 'Hours to pull and set the pump');
  const hoursPerExtraFoot = number(input.hoursPerExtraFoot ?? 0, 'Hours per extra drop-pipe foot');
  const hoursTank = number(input.hoursTank ?? 0, 'Hours to set a tank');
  const hoursPitless = number(input.hoursPitless ?? 0, 'Hours to replace a pitless');
  const hoursStuckPull = number(input.hoursStuckPull ?? 0, 'Hours for a stuck pull');
  const hoursSwitch = number(input.hoursSwitch ?? 0, 'Hours for the switch / control box');
  const hoursPerExtraCableFoot = number(input.hoursPerExtraCableFoot ?? 0, 'Hours per extra cable foot');
  const hoursVfd = number(input.hoursVfd ?? 0, 'Hours for a constant-pressure drive');
  const siteHours = number(input.siteHours ?? 0, 'Site / travel hours');

  const pumpCost = number(input.pumpCost ?? 0, 'Pump cost');
  const tankCost = number(input.tankCost ?? 0, 'Tank cost');
  const pitlessCost = number(input.pitlessCost ?? 0, 'Pitless adapter');
  const cablePerFoot = number(input.cablePerFoot ?? 0, 'Cable cost per foot');
  const switchCost = number(input.switchCost ?? 0, 'Switch / control box');
  const vfdCost = number(input.vfdCost ?? 0, 'Constant-pressure drive');
  const hoistFee = number(input.hoistFee ?? 0, 'Pump hoist / crane');
  const permitFee = number(input.permitFee ?? 0, 'Permit fee');

  const hourlyWage = number(input.hourlyWage ?? 0, 'Hourly wage');
  const burdenRate = number(input.burdenRate ?? 0, 'Payroll burden');
  const travelAndEquipment = number(input.travelAndEquipment ?? 0, 'Travel and equipment');
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const loadedWage = hourlyWage * (1 + burdenRate / 100);

  const tripHours = hoursTrip;
  const pumpHours = hoursPumpBase;
  const footageHours = extraFeet * hoursPerExtraFoot;
  const tankHours = replaceTank ? hoursTank : 0;
  const pitlessHours = replacePitless ? hoursPitless : 0;
  const stuckHours = stuckPump ? hoursStuckPull : 0;
  const switchHours = replaceSwitch ? hoursSwitch : 0;
  const cableHours = extraCableFeet * hoursPerExtraCableFoot;
  const vfdHours = addVfd ? hoursVfd : 0;
  const accessHours = pitlessHours + stuckHours;
  const packageHours = tankHours + switchHours + vfdHours;
  const runHours = footageHours + cableHours;
  const totalHours = tripHours + pumpHours + runHours + accessHours + packageHours + siteHours;
  const laborCost = totalHours * loadedWage;

  const pumpMaterial = pumpCost;
  const tankMaterial = replaceTank ? tankCost : 0;
  const pitlessMaterial = replacePitless ? pitlessCost : 0;
  const cableMaterial = extraCableFeet * cablePerFoot;
  const switchMaterial = replaceSwitch ? switchCost : 0;
  const vfdMaterial = addVfd ? vfdCost : 0;
  const hoistMaterial = type === 'submersible' ? hoistFee : 0;
  const permitMaterial = permitFee;
  const materialCost = pumpMaterial + tankMaterial + pitlessMaterial + cableMaterial
    + switchMaterial + vfdMaterial + hoistMaterial + permitMaterial;
  const softCost = travelAndEquipment;

  const directCost = laborCost + materialCost + softCost;
  const overhead = directCost * overheadRate / 100;
  const totalCost = directCost + overhead;
  const price = totalCost / (1 - targetMargin / 100);
  const profit = price - totalCost;

  const hasProposed = input.proposedPrice !== null && input.proposedPrice !== undefined && input.proposedPrice !== '';
  const proposedPrice = hasProposed ? number(input.proposedPrice, 'Price you are considering') : null;

  const costShare = (amount) => (totalCost === 0 ? 0 : amount / totalCost * 100);
  const hourShare = (amount) => (totalHours === 0 ? 0 : amount / totalHours * 100);

  return {
    type,
    work,
    hp,
    pitless,
    wellDepthFeet,
    includedFootage,
    extraFeet,
    cableFeet,
    includedCableFeet,
    extraCableFeet,
    stuckPump,
    addVfd,
    replaceTank,
    replaceSwitch,
    replacePitless,
    loadedWage,
    tripHours,
    pumpHours,
    footageHours,
    tankHours,
    pitlessHours,
    stuckHours,
    switchHours,
    cableHours,
    vfdHours,
    accessHours,
    packageHours,
    runHours,
    siteHours,
    totalHours,
    laborCost,
    pumpMaterial,
    tankMaterial,
    pitlessMaterial,
    cableMaterial,
    switchMaterial,
    vfdMaterial,
    hoistMaterial,
    permitMaterial,
    materialCost,
    travelAndEquipment,
    softCost,
    overhead,
    directCost,
    totalCost,
    price,
    profit,
    pricePerFoot: wellDepthFeet === 0 ? null : price / wellDepthFeet,
    pricePerExtraFoot: extraFeet === 0 ? null : price / extraFeet,
    effectiveHourlyRate: totalHours === 0 ? null : price / totalHours,
    breakEvenPrice: totalCost,
    shares: {
      labor: costShare(laborCost),
      material: costShare(materialCost),
      soft: costShare(softCost),
      overhead: costShare(overhead),
    },
    hourShares: {
      trip: hourShare(tripHours),
      pump: hourShare(pumpHours),
      run: hourShare(runHours),
      access: hourShare(accessHours),
      extras: hourShare(packageHours),
      site: hourShare(siteHours),
    },
    proposed: proposedPrice === null ? null : {
      price: proposedPrice,
      profit: proposedPrice - totalCost,
      margin: proposedPrice === 0 ? 0 : (proposedPrice - totalCost) / proposedPrice * 100,
      perFoot: wellDepthFeet === 0 ? null : proposedPrice / wellDepthFeet,
      hourlyRate: totalHours === 0 ? null : proposedPrice / totalHours,
      belowBreakEven: proposedPrice < totalCost,
    },
  };
}

/**
 * Format a bid as a plain-text draft the shop can paste into a
 * proposal. Costs, wages, and invoices are omitted on purpose — this is
 * the customer-facing side.
 */
export function formatBidSummary(result, jobLabel = 'Well pump replacement') {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const perFoot = result.pricePerFoot === null
    ? 'n/a'
    : `${money(result.pricePerFoot)} / ft of well depth`;
  const type = TYPE_PRESETS.find((item) => item.id === result.type)?.label ?? result.type;
  const work = WORK_PRESETS.find((item) => item.id === result.work)?.label ?? result.work;
  const hp = HP_PRESETS.find((item) => item.id === result.hp)?.label ?? result.hp;
  const pitless = PITLESS_PRESETS.find((item) => item.id === result.pitless)?.label ?? result.pitless;
  const tank = result.replaceTank ? 'new pressure tank included' : 'existing tank kept';
  const stuck = result.stuckPump ? 'stuck-pump pull included' : 'no stuck-pump pull this bid';
  const vfd = result.addVfd ? 'constant-pressure drive included' : 'no constant-pressure drive this bid';
  return [
    'WELL PUMP / PRESSURE TANK BID',
    '',
    `Proposed well-pump price: ${money(result.price)}`,
    `Scope: ${jobLabel}; ${type}; ${hp}; ${work}`,
    `Price per foot of well depth: ${perFoot}`,
    `Crew labor: ${result.totalHours.toFixed(1)} crew-hours`,
    '',
    'SCOPE BASIS',
    `- ${type}; ${result.wellDepthFeet} ft of well (${result.extraFeet} ft past the included ${result.includedFootage} ft)`,
    `- Pitless: ${pitless}; well cable: ${result.cableFeet} ft`,
    `- ${tank}; ${stuck}; ${vfd}`,
    `- Pump labor: ${result.pumpHours.toFixed(1)} h; extra footage / cable: ${result.runHours.toFixed(1)} h; pitless / stuck pull: ${result.accessHours.toFixed(1)} h`,
    '',
    'This is a draft for review. Confirm well depth, horsepower, tank size, pitless condition, cable, permits, and all pricing before sending. It is not a well-drilling specification, a water-quality report, a permit, or an engineering stamp.',
  ].join('\n');
}

proposal-terms.mjs.text:
// Carry the proposal terms in a bid link, on a calculator that does not use the
// shared bid spec.
//
// Why this exists
// ---------------
// The proposal panel `adopt.mjs` generates asks for five things that are not
// part of any calculator's arithmetic: the deposit percentage, how long the
// price is held, the not-included list, the payment terms, and a notes block.
// They are the terms of the offer rather than the price of the work, which is
// why every share encoder on this site was built without them — and why, for a
// while, all 48 adopting tools dropped all five.
//
// The consequence is not a cosmetic one. Driven in Chromium on 2026-08-29
// against `artificial-turf-bid-calculator`, a bid priced at a 50% deposit held
// for 15 days reopened from its own link at the venture's defaults, and the
// customer proposal the recipient printed asked for $1,640.44 on acceptance
// where the sender's sheet said $2,734.07. The headline figure matched to the
// cent, so nothing on either page suggested a disagreement.
//
// 36 of those tools share a bid spec, and the fix there is part of it: a `text`
// kind beside `numbers`, `flags` and `choices`, and `withProposalTerms` folding
// the five ids in. The other 12 predate that spec and each keep a hand-written
// allowlist in their own `share.mjs` — three different encodings between them
// (a JSON payload, a query string derived from `calc.mjs`, and a third from a
// cost-id list). Rewriting all three to a shared spec would mean touching the
// input handling of twelve working calculators to fix a field none of them
// compute with.
//
// So the terms travel *beside* whatever the venture already writes, in one
// parameter the venture's own decoder never sees:
//
//   #<the venture's own payload>&pfterms=<the five terms, url-encoded>
//
// The value is URI-encoded as a whole, so a `&` or `=` inside a payment-terms
// clause cannot be mistaken for a parameter boundary, and a venture that
// serializes JSON gets its payload back byte-for-byte after `splitTerms`.
//
// One list, guarded rather than shared
// ------------------------------------
// The ids here are also declared in `adopt.mjs` (which builds the panel) and in
// the 36 vendored `share.mjs` copies (which carry them in the shared spec).
// Three declarations, because a venture directory is published on its own and
// an import across the tree would 404 on the live site — the same reason
// `proposal.mjs` is vendored rather than imported. `term-ids.test.mjs` is what
// makes them one list in practice: add a term to the panel without adding it
// here, and it fails.

/** Numeric terms: the deposit split and how long the price is held. */
export const PROPOSAL_TERM_NUMBERS = Object.freeze(['depositPercent', 'validDays']);

/** Prose terms, all three of them textareas on the panel. */
export const PROPOSAL_TERM_TEXT = Object.freeze([
  'proposalExclusions', 'paymentTerms', 'proposalNotes',
]);

/**
 * A ceiling on one block of prose, matching `MAX_LINK_VALUE` in
 * `platform/pages/link.mjs` and `MAX_TERM_TEXT` in the shared bid spec, so all
 * three share mechanisms on this site agree about what fits in a fragment.
 */
export const MAX_TERM_TEXT = 512;

/** The parameter the terms ride in. Prefixed, so a venture id cannot collide. */
export const TERMS_PARAM = 'pfterms';

/** What the setter calls these fields — the label on the panel, not the id. */
const TERM_LABELS = Object.freeze({
  proposalExclusions: 'not-included list',
  paymentTerms: 'payment terms',
  proposalNotes: 'notes',
});

/**
 * Only a finite, non-negative number, the same contract every calculator here
 * enforces on input. A deposit of `-5` or `NaN` never reaches the panel.
 */
function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

/**
 * Prose as typed, newlines included — an exclusions list is a list, and it
 * prints as one on the customer's sheet. Two things come out: the control
 * characters no textarea produces and no proposal should render, and the
 * surrounding whitespace, so a field holding a stray newline reads as empty
 * rather than as terms the sender wrote.
 *
 * Over-long is `null` — dropped, never truncated. Half a payment-terms clause
 * presented to the recipient as the sender's terms is worse than an empty
 * field, and `overlongTermsNote` is what tells the sender which one stayed
 * behind rather than letting the customer find out.
 */
function usableText(value) {
  if (typeof value !== 'string') return null;
  // eslint-disable-next-line no-control-regex
  const clean = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
  if (!clean) return null;
  return clean.length > MAX_TERM_TEXT ? null : clean;
}

/**
 * The five terms as a query string, or `''` when the setter has typed none of
 * them worth carrying. Pure: no DOM, no storage.
 */
export function encodeTerms(values) {
  const params = new URLSearchParams();
  for (const id of PROPOSAL_TERM_NUMBERS) {
    const value = usableNumber(values?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of PROPOSAL_TERM_TEXT) {
    const value = usableText(values?.[id]);
    if (value !== null) params.set(id, value);
  }
  return params.toString();
}

/**
 * Back to values, re-validated exactly as on the way out.
 *
 * A fragment is the one part of these pages a stranger can write, so this
 * treats it as hostile: an id the panel does not offer, a deposit that is not a
 * number, a control character, or a megabyte of prose all drop out here rather
 * than reaching a document the contractor is about to print for a customer.
 */
export function decodeTerms(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const values = {};
  for (const id of PROPOSAL_TERM_NUMBERS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) values[id] = String(value);
  }
  for (const id of PROPOSAL_TERM_TEXT) {
    if (!params.has(id)) continue;
    const value = usableText(params.get(id));
    if (value !== null) values[id] = value;
  }
  return values;
}

/**
 * Append the terms to a hash the venture's own encoder produced.
 *
 * Returns the payload unchanged when there is nothing to carry, so a page that
 * has not adopted the proposal panel — or a setter who left the terms at their
 * defaults with nothing typed — gets exactly the link it got before.
 */
export function withTerms(payload, values) {
  const encoded = encodeTerms(values);
  const base = typeof payload === 'string' ? payload : '';
  if (!encoded) return base;
  const segment = `${TERMS_PARAM}=${encodeURIComponent(encoded)}`;
  return base ? `${base}&${segment}` : segment;
}

/**
 * The venture's own payload and the terms, separated.
 *
 * The venture half comes back byte-for-byte: the ventures on this path
 * serialize JSON and hand it to `JSON.parse`, so a stray `&pfterms=...` left on
 * the end would not merely add a field — it would fail the parse and the whole
 * bid would refuse to open.
 */
export function splitTerms(hash) {
  const raw = typeof hash === 'string' ? hash.replace(/^[#?]/, '') : '';
  const marker = `${TERMS_PARAM}=`;
  const at = raw.indexOf(marker);
  if (at < 0) return { payload: raw, terms: '' };
  const before = at > 0 && raw[at - 1] === '&' ? at - 1 : at;
  const after = raw.indexOf('&', at + marker.length);
  const encoded = after < 0 ? raw.slice(at + marker.length) : raw.slice(at + marker.length, after);
  let terms = '';
  try {
    terms = decodeURIComponent(encoded);
  } catch {
    // A hand-mangled fragment is not terms. The bid still opens.
  }
  const payload = raw.slice(0, before) + (after < 0 ? '' : raw.slice(after));
  return { payload: payload.replace(/^&/, ''), terms };
}

/**
 * The terms this page is showing, read off the panel.
 *
 * `lookup` is the page's own `el` — id to element, or null — kept as an
 * argument so this module needs no DOM to test. A page without the panel has no
 * such elements and yields `{}`, which encodes to `''` and changes no link.
 */
export function readTerms(lookup) {
  const values = {};
  if (typeof lookup !== 'function') return values;
  for (const id of [...PROPOSAL_TERM_NUMBERS, ...PROPOSAL_TERM_TEXT]) {
    let field = null;
    try {
      field = lookup(id);
    } catch {
      // `el` throws on some pages when the id is absent. Absent is the answer.
    }
    if (field && typeof field.value === 'string') values[id] = field.value;
  }
  return values;
}

/**
 * Write the terms onto the panel and let the page recompute.
 *
 * Both events, bubbling, exactly as a person typing would: the proposal region
 * listens on the document and redraws the deposit row from them. Returns how
 * many fields were written, so a caller can say so.
 */
export function applyTerms(values, lookup) {
  if (typeof lookup !== 'function') return 0;
  let written = 0;
  for (const [id, value] of Object.entries(values || {})) {
    let field = null;
    try {
      field = lookup(id);
    } catch {
      field = null;
    }
    if (!field) continue;
    field.value = String(value);
    field.dispatchEvent(new Event('input', { bubbles: true }));
    field.dispatchEvent(new Event('change', { bubbles: true }));
    written += 1;
  }
  return written;
}

/** Which prose terms are too long to ride in a link. */
export function overlongTerms(values) {
  return PROPOSAL_TERM_TEXT.filter((id) => {
    const raw = values?.[id];
    return typeof raw === 'string' && raw.trim().length > MAX_TERM_TEXT;
  });
}

/**
 * The sentence a page shows when a term did not fit, or `''` when all of them
 * did. Assembled here rather than in each page: this wording ships on every
 * calculator with a proposal, and the alternative is the same sentence written
 * forty-eight times and corrected in one of them.
 */
export function overlongTermsNote(values) {
  const left = overlongTerms(values).map((id) => TERM_LABELS[id] ?? id);
  if (left.length === 0) return '';
  const named = left.length === 1
    ? left[0]
    : `${left.slice(0, -1).join(', ')} and ${left[left.length - 1]}`;
  return `your ${named} ${left.length === 1 ? 'is' : 'are'} too long to fit in a link `
    + `and stayed behind — send ${left.length === 1 ? 'it' : 'them'} separately if the wording matters`;
}

proposal.mjs.text:
// Turns a finished bid into the document the contractor actually hands the
// customer: a one-page proposal they can print or "Save as PDF" from the
// browser.
//
// Why this exists
// ---------------
// Every bid calculator in this portfolio already ends at a number and a
// plain-text blurb to paste somewhere. That is where the tool stops and the
// contractor's evening starts: retyping the scope into Word, remembering the
// deposit split, guessing how long the price should stand. The proposal is the
// thing that wins or loses the job, and it was the one artifact none of these
// tools produced.
//
// Deliberately NOT a contract
// ---------------------------
// This renders the contractor's own words and numbers into a tidy layout. It
// invents no legal terms, warranties, lien language, or cancellation rights —
// every clause on the page is text the user typed or left blank. A "proposal"
// that shipped boilerplate terms drafted by a calculator would be exactly the
// legal exposure `PRODUCT_PLAYBOOK.md` §5b tells us to avoid, and it would be
// wrong in most jurisdictions anyway.
//
// Privacy
// -------
// `loadCompany` / `saveCompany` persist the *contractor's own* business block
// (their name, phone, licence) so they type it once. The customer's name and
// address are never persisted: that is a third party's personal data sitting on
// someone else's device, and re-typing it per job is cheap. Nothing here
// touches the network.
//
// This file is generic on purpose — no trade, no venture, no storage key baked
// in — so it can be copied verbatim into any calculator in `ventures/`. See the
// venture README for the wiring steps.

/** Fields of the contractor's own business block, in display order. */
export const COMPANY_FIELDS = Object.freeze([
  'companyName', 'companyPhone', 'companyEmail', 'companyLicense', 'companyAddress',
]);

/** Fields describing the customer and the job. Never persisted. */
export const CLIENT_FIELDS = Object.freeze([
  'clientName', 'clientAddress',
]);

/** Commercial terms the contractor controls. */
export const TERM_FIELDS = Object.freeze([
  'depositPercent', 'validDays', 'paymentTerms', 'proposalNotes', 'proposalExclusions',
]);

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function text(value) {
  return String(value ?? '').trim();
}

function number(value, name, { min = 0, max = Infinity } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (result > max) throw new Error(`${name} must be at most ${max}`);
  return result;
}

/**
 * A figure for the customer's copy.
 *
 * `currency` defaults to `'$'`, which is what every trade in this portfolio
 * quotes in and what all 102 adopters rendered before it was a parameter — so
 * an unchanged caller gets a byte-identical document.
 *
 * It exists because the document is not only a US construction bid. A
 * freelancer quoting a translation names their own currency on the page, and
 * printing `$1,200.00` on a quote the client will pay in euros is not a display
 * nicety: it misstates the price on the one sheet that is meant to settle it.
 * The venture passes whatever its own currency field says.
 *
 * A label is spaced from the figure and a symbol is not — `USD 1,200.00` but
 * `$1,200.00` and `€1,200.00` — decided by whether the currency ends in a
 * letter, which is the only difference a reader would notice between the two.
 *
 * That space is a non-breaking one, written as an escape so it cannot be
 * mistaken for an ordinary space by anyone reading this file or matching
 * against its output. A quote is a printed document with a narrow price
 * column, and "USD" left stranded at the end of a line with its figure on the
 * next is the one place this layout can break in a way the customer sees.
 */
export function money(value, currency = '$') {
  // Sign goes outside the currency symbol: "-$9.24", not "$-9.24". The old
  // spelling put it inside, which is what interpolating a negative straight
  // after a "$" gets you, and it reads as a typo on a document a contractor
  // hands a customer.
  //
  // Round to cents *before* choosing the sign. A delta of two equal figures
  // lands on -0, and a residual like -0.004 rounds to zero at cent precision;
  // both used to print "$-0.00" — a line that is exactly break-even claiming
  // to be down money.
  const cents = Math.round(Math.abs(value) * 100);
  const sign = cents === 0 ? '' : value < 0 ? '-' : '';
  const amount = (cents / 100).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const unit = text(currency) || '$';
  return `${sign}${unit}${/[A-Za-z]$/.test(unit) ? '\u00a0' : ''}${amount}`;
}

/**
 * Split a textarea into trimmed, non-empty lines. Blank lines are how people
 * space out a scope list; they should not become empty bullets.
 */
export function lines(value) {
  return text(value)
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

/**
 * Fill scope templates from a calculator's result, dropping any line whose
 * figures are not there.
 *
 * Every adoption batch so far has lost a line to the same defect: each
 * calculator names its result differently, `result.doorClass` or `run.material`
 * resolves to `undefined` rather than throwing, and the customer's scope reads
 * "undefined ft of undefined" while every suite stays green. Guessing is the
 * problem; this makes guessing wrong *visible* instead of silent.
 *
 * A template is `'Install {totalLinearFeet} ft of {fenceName}'`, or an object
 * `{ line, when }` where `when` names a field that must be truthy for the line
 * to appear at all.
 *
 * `{ each, line, when }` renders one line **per element** of the array at
 * `each`, with `{field}` reading that element rather than the result root.
 * Half the calculators here price an itemised job — rooms of flooring, gutter
 * runs, trees, kitchen exhaust components — and a homeowner collecting three
 * bids compares the line items, not a total. Without this the only scope such
 * a trade could draft is "Perform the work described above", which the README
 * is explicit is worth less than no proposal at all. `when` is read against
 * the element too, so a row the contractor left at zero stays off the quote:
 *
 * ```json
 * { "each": "rooms", "when": "hours", "line": "{name} — {squareFeet~0} sq ft" }
 * ```
 *
 * Elements are not truncated. Every row the contractor entered is a row they
 * intend to be paid for, and "…and 4 more" on a document someone signs is a
 * dispute waiting to happen.
 *
 * `{field+s}` is that field's plural suffix — `'s'` unless the value is exactly
 * one — so `'{gates} gate{gates+s}'` reads "1 gate" and "3 gates". Without it
 * the obvious thing to write is `'{gates} gate{gates}'`, which prints
 * "3 gate3" on a customer's quote.
 *
 * `{field~2}` rounds to that many decimals and groups thousands, so a derived
 * figure reads "48.89 yd²" and "1,600 sq ft" rather than "48.888888888888886"
 * and "1600". Anything computed — a yardage, a tonnage, a square count — needs
 * it: a quote carrying fifteen decimal places tells the customer the number was
 * produced by a machine that was not being watched.
 *
 * A placeholder that resolves to `undefined`, `null`, `''`,
 * `NaN`, or `Infinity` drops its whole line — a scope with one line missing is
 * a scope the contractor edits, whereas a scope reading `undefined` is one they
 * hand to a customer without noticing.
 *
 * Dropping is not the safety property on its own: an empty scope is also wrong,
 * and `platform/proposal/verify.mjs` fails a page whose default scope comes out
 * empty. Between them, a mis-named field cannot reach a customer quietly.
 *
 * @param {Array<string|{line: string, when?: string, each?: string}>} templates
 * @param {object} values The calculator's result (and anything else to read).
 * @returns {string[]}
 */
export function scopeLines(templates, values) {
  const missing = (value) => value === undefined || value === null || value === ''
    || (typeof value === 'number' && !Number.isFinite(value));

  const readFrom = (scope, path) => String(path).split('.')
    .reduce((node, key) => (node === null || node === undefined ? undefined : node[key]), scope);

  /**
   * One template line against one scope, or `null` if any placeholder in it is
   * missing. Shared by plain lines and `each` rows on purpose: a row must drop
   * on a missing figure by exactly the same rule as a top-level line, or the
   * word "undefined" reaches the customer through whichever path was written
   * second.
   */
  const render = (line, scope) => {
    let complete = true;
    const rendered = line.replace(
      /\{([A-Za-z0-9_.]+?)(?:\+([A-Za-z]+)|~(\d))?\}/g,
      (_match, path, plural, decimals) => {
        const value = readFrom(scope, path);
        if (missing(value)) { complete = false; return ''; }
        if (plural !== undefined) return Number(value) === 1 ? '' : plural;
        if (decimals !== undefined) {
          const number = Number(value);
          if (!Number.isFinite(number)) { complete = false; return ''; }
          return number.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: Number(decimals),
          });
        }
        return String(value);
      },
    );
    return complete && rendered.trim() ? rendered.trim() : null;
  };

  const filled = [];
  for (const template of templates ?? []) {
    const line = typeof template === 'string' ? template : template?.line;
    if (typeof line !== 'string') continue;
    const each = typeof template === 'object' ? template.each : undefined;

    if (each !== undefined) {
      const rows = readFrom(values, each);
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (row === null || typeof row !== 'object') continue;
        if (template.when !== undefined && !readFrom(row, template.when)) continue;
        const rendered = render(line, row);
        if (rendered !== null) filled.push(rendered);
      }
      continue;
    }

    if (typeof template === 'object' && template.when !== undefined && !readFrom(values, template.when)) continue;
    const rendered = render(line, values);
    if (rendered !== null) filled.push(rendered);
  }
  return filled;
}

/**
 * `YYYY-MM-DD` plus a whole number of days, in UTC.
 *
 * Local-time date arithmetic silently shifts by a day across a DST boundary,
 * which on a quote-expiry date is a real dispute with a customer.
 */
export function addDays(isoDate, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) throw new Error('Issue date must be YYYY-MM-DD');
  const [, year, month, day] = match;
  const stamp = Date.UTC(Number(year), Number(month) - 1, Number(day));
  if (Number.isNaN(stamp)) throw new Error('Issue date must be a real date');
  return new Date(stamp + number(days, 'Valid days') * 86_400_000)
    .toISOString()
    .slice(0, 10);
}

/** `2026-08-26` → `26 August 2026`. Unambiguous to both US and non-US readers. */
export function formatDate(isoDate) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) return text(isoDate);
  const [, year, month, day] = match;
  const monthName = new Date(Date.UTC(Number(year), Number(month) - 1, 1))
    .toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
  return `${Number(day)} ${monthName} ${year}`;
}

/**
 * A short, stable reference the contractor and the customer can both quote on
 * the phone. Derived from the issue date and the customer name so that
 * re-printing the same proposal gives the same number, and two proposals
 * written the same day for different customers do not collide.
 */
export function referenceFor(issuedOn, clientName) {
  const compact = text(issuedOn).replaceAll('-', '');
  let hash = 0;
  for (const character of text(clientName).toUpperCase()) {
    hash = (hash * 31 + character.codePointAt(0)) % 1_048_576;
  }
  return `Q-${compact}-${hash.toString(36).toUpperCase().padStart(4, '0').slice(-4)}`;
}

/**
 * Assemble and validate a proposal.
 *
 * Throws on the things that would embarrass the contractor in front of a
 * customer — no business name, no customer name, a zero price, a deposit over
 * 100% — rather than rendering a document with a hole in it.
 */
export function buildProposal(input = {}) {
  const companyName = text(input.companyName);
  if (!companyName) throw new Error('Add your business name before printing a proposal');
  const clientName = text(input.clientName);
  if (!clientName) throw new Error('Add the customer name before printing a proposal');

  const price = number(input.price, 'Price', { min: 0 });
  if (price <= 0) throw new Error('Price a job before printing a proposal');

  const depositPercent = number(input.depositPercent ?? 0, 'Deposit', { min: 0, max: 100 });
  const validDays = number(input.validDays ?? 0, 'Valid days', { min: 0, max: 3650 });
  const issuedOn = text(input.issuedOn) || new Date().toISOString().slice(0, 10);

  // Rounded to cents here, not at display time, and the balance taken as the
  // remainder. The customer adds the two lines up: if the deposit rounds up and
  // the balance rounds down independently, the printed figures miss the printed
  // total by a cent, and the contractor has to explain it on the phone.
  const depositAmount = Math.round(price * depositPercent) / 100;

  return {
    reference: referenceFor(issuedOn, clientName),
    issuedOn,
    validDays,
    validUntil: validDays === 0 ? null : addDays(issuedOn, validDays),
    company: {
      name: companyName,
      phone: text(input.companyPhone),
      email: text(input.companyEmail),
      license: text(input.companyLicense),
      address: text(input.companyAddress),
    },
    client: {
      name: clientName,
      address: text(input.clientAddress),
    },
    job: {
      title: text(input.jobTitle) || 'Proposed work',
      scope: lines(input.scope),
      exclusions: lines(input.proposalExclusions),
      notes: text(input.proposalNotes),
    },
    pricing: {
      price,
      depositPercent,
      depositAmount,
      balanceAmount: price - depositAmount,
      paymentTerms: text(input.paymentTerms),
    },
  };
}

function block(title, body) {
  return body ? `<div class="pr-block"><h3>${escapeHtml(title)}</h3>${body}</div>` : '';
}

function list(items) {
  return items.length === 0
    ? ''
    : `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function paragraphs(value) {
  return value ? `<p>${escapeHtml(value).replaceAll('\n', '<br>')}</p>` : '';
}

/**
 * Render the proposal as the HTML that goes inside the page's print container.
 *
 * Returns a fragment, not a whole document: the page owns the print stylesheet,
 * so the same markup is what the contractor previews on screen and what comes
 * out of the printer. A separate print-only document is how the two drift.
 *
 * @param {ReturnType<typeof buildProposal>} proposal
 * @param {object} [options]
 * @param {string} [options.disclaimer] Sentence to print in the footer. The
 *   caller supplies it so each trade can name its own regulator and scope.
 * @param {string} [options.currency] Prefix for every figure on the sheet.
 *   Defaults to `'$'`; see `money`.
 */
export function renderProposalHtml(proposal, { disclaimer = '', currency = '$' } = {}) {
  const { company, client, job, pricing } = proposal;
  const amount = (value) => money(value, currency);

  const contact = [company.phone, company.email, company.address]
    .filter(Boolean)
    .map((line) => `<span>${escapeHtml(line)}</span>`)
    .join('');

  const validity = proposal.validUntil
    ? `<p class="pr-validity">This price is held until <strong>${escapeHtml(formatDate(proposal.validUntil))}</strong> (${proposal.validDays} days from issue).</p>`
    : '';

  const depositRow = pricing.depositPercent > 0
    ? `<tr><td>Deposit due on acceptance (${pricing.depositPercent}%)</td><td>${amount(pricing.depositAmount)}</td></tr>
       <tr><td>Balance due on completion</td><td>${amount(pricing.balanceAmount)}</td></tr>`
    : '';

  return `
    <article class="pr-doc">
      <header class="pr-head">
        <div>
          <h2>${escapeHtml(company.name)}</h2>
          <div class="pr-contact">${contact}</div>
          ${company.license ? `<p class="pr-license">Licence ${escapeHtml(company.license)}</p>` : ''}
        </div>
        <div class="pr-meta">
          <p class="pr-kicker">Proposal</p>
          <p><strong>${escapeHtml(proposal.reference)}</strong></p>
          <p>${escapeHtml(formatDate(proposal.issuedOn))}</p>
        </div>
      </header>

      <div class="pr-parties">
        <div class="pr-block"><h3>Prepared for</h3>
          <p><strong>${escapeHtml(client.name)}</strong></p>
          ${paragraphs(client.address)}
        </div>
        <div class="pr-block"><h3>Work</h3>
          <p><strong>${escapeHtml(job.title)}</strong></p>
        </div>
      </div>

      ${block('Scope of work', list(job.scope))}
      ${block('Not included', list(job.exclusions))}
      ${block('Notes', paragraphs(job.notes))}

      <table class="pr-price">
        <tbody>
          <tr class="pr-total"><td>Total price</td><td>${amount(pricing.price)}</td></tr>
          ${depositRow}
        </tbody>
      </table>
      ${validity}
      ${block('Payment terms', paragraphs(pricing.paymentTerms))}

      <div class="pr-sign">
        <div><span class="pr-rule"></span><p>Customer signature</p></div>
        <div><span class="pr-rule"></span><p>Date</p></div>
      </div>

      ${disclaimer ? `<p class="pr-disclaimer">${escapeHtml(disclaimer)}</p>` : ''}
    </article>
  `;
}

/**
 * Read the saved business block. A corrupt or absent entry is an empty block,
 * never an exception: a broken localStorage value must not stop someone
 * pricing a job.
 */
export function loadCompany(storage, key) {
  try {
    const saved = JSON.parse(storage?.getItem(key) || '{}');
    return Object.fromEntries(
      COMPANY_FIELDS.map((field) => [field, text(saved?.[field])]),
    );
  } catch {
    return Object.fromEntries(COMPANY_FIELDS.map((field) => [field, '']));
  }
}

/**
 * Persist the business block only. `CLIENT_FIELDS` are excluded by
 * construction, not by the caller remembering to strip them.
 */
export function saveCompany(storage, key, values = {}) {
  const payload = Object.fromEntries(
    COMPANY_FIELDS.map((field) => [field, text(values[field])]),
  );
  try {
    storage?.setItem(key, JSON.stringify(payload));
  } catch {
    // A full or disabled localStorage is not worth an error in front of the
    // customer; the proposal still prints, it just will not be pre-filled next
    // time.
  }
  return payload;
}

export function forgetCompany(storage, key) {
  try {
    storage?.removeItem(key);
  } catch {
    // Same reasoning as saveCompany.
  }
}

share.mjs.text:
// Shareable bid link. A well-service or plumbing shop comparing a takeoff
// with a partner, a supply-house counter rep, or an office manager needs the
// recipient to see the exact same job -- depth, horsepower, pitless
// condition, cable, tank, every hour and rate -- not just the headline price
// a screenshot would show. Retyping thirty-plus numbers is how that
// comparison never happens. The transform is pure: no DOM, no storage, no
// network, and everything after the # never reaches a server.
//
// Enum fields are checked against calc.mjs's own preset ids rather than a
// hand-duplicated list, so a crafted or stale link can only set them to
// values the form could have produced -- the drift class CLAUDE.md's
// "RENAME SUSPECTED" note and #2962 both describe for a select field left off
// an allowlist.
//
// The deposit, validity window, and the proposal panel's three prose terms
// ride separately via `proposal-terms.mjs` (`withTerms`/`splitTerms`), the
// same mechanism `fireplace-insert-bid-calculator` and `ev-charger-bid-
// calculator` use -- not duplicated here, so the calculators cannot drift on
// how those five fields are carried. Company and customer details are
// deliberately left out: they persist per-device via `proposal.mjs`'s
// `loadCompany`/`saveCompany`, and a customer's name or address has no
// business riding in a URL two people paste into text or email.

import { TYPE_PRESETS, WORK_PRESETS, HP_PRESETS, PITLESS_PRESETS } from './calc.mjs';

export const NUMBER_FIELD_IDS = [
  'wellDepthFeet', 'includedFootage', 'cableFeet', 'includedCableFeet',
  'hoursTrip', 'hoursPumpBase', 'hoursPerExtraFoot', 'hoursTank', 'hoursPitless',
  'hoursStuckPull', 'hoursSwitch', 'hoursPerExtraCableFoot', 'hoursVfd', 'siteHours',
  'pumpCost', 'tankCost', 'pitlessCost', 'cablePerFoot', 'switchCost', 'vfdCost', 'hoistFee', 'permitFee',
  'hourlyWage', 'burdenRate', 'travelAndEquipment', 'overheadRate', 'targetMargin',
  'proposedPrice',
];

export const BOOLEAN_FIELD_IDS = ['stuckPump', 'addVfd'];

// Mirrors the <select id="type"> / <select id="work"> / <select id="hp"> /
// <select id="pitless"> options in index.html, sourced from calc.mjs so the
// allowed values cannot drift out of step with the presets the form offers.
export const TYPE_VALUES = TYPE_PRESETS.map((preset) => preset.id);
export const WORK_VALUES = WORK_PRESETS.map((preset) => preset.id);
export const HP_VALUES = HP_PRESETS.map((preset) => preset.id);
export const PITLESS_VALUES = PITLESS_PRESETS.map((preset) => preset.id);

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

function usableEnum(value, allowed) {
  return allowed.includes(value) ? value : null;
}

export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of NUMBER_FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of BOOLEAN_FIELD_IDS) {
    if (inputs?.[id] !== undefined) params.set(id, inputs[id] ? '1' : '0');
  }
  const type = usableEnum(inputs?.type, TYPE_VALUES);
  if (type !== null) params.set('type', type);
  const work = usableEnum(inputs?.work, WORK_VALUES);
  if (work !== null) params.set('work', work);
  const hp = usableEnum(inputs?.hp, HP_VALUES);
  if (hp !== null) params.set('hp', hp);
  const pitless = usableEnum(inputs?.pitless, PITLESS_VALUES);
  if (pitless !== null) params.set('pitless', pitless);
  return params.toString();
}

export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const inputs = {};
  for (const id of NUMBER_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  for (const id of BOOLEAN_FIELD_IDS) {
    if (params.has(id)) inputs[id] = params.get(id) === '1';
  }
  if (params.has('type')) {
    const type = usableEnum(params.get('type'), TYPE_VALUES);
    if (type !== null) inputs.type = type;
  }
  if (params.has('work')) {
    const work = usableEnum(params.get('work'), WORK_VALUES);
    if (work !== null) inputs.work = work;
  }
  if (params.has('hp')) {
    const hp = usableEnum(params.get('hp'), HP_VALUES);
    if (hp !== null) inputs.hp = hp;
  }
  if (params.has('pitless')) {
    const pitless = usableEnum(params.get('pitless'), PITLESS_VALUES);
    if (pitless !== null) inputs.pitless = pitless;
  }
  return inputs;
}

